class Solution {
    public int numIslands(char[][] grid) {
        int count = 0;
        for (int row = 0; row < grid.length; row++) {
            for (int col = 0; col < grid[row].length; col++) {
                if (grid[row][col] == '1') {
                    count++;
                    fill(grid, row, col);
                }
            }
        }
        return count;
    }

    private void fill(char[][] grid, int row, int col) {
        if (row < 0 || col < 0 || row >= grid.length || col >= grid[row].length || grid[row][col] != '1') {
            return;
        }
        grid[row][col] = '0';
        fill(grid, row + 1, col);
        fill(grid, row - 1, col);
        fill(grid, row, col + 1);
        fill(grid, row, col - 1);
    }
}
